def test_reproduce():
    factory = RequestFactory()
    request = factory.get('/offers/my-offer/')

    Account.objects.create(slug='my-offer')

    try:
        # Simulating TemplateView.get(request, *args, **kwargs)
        # The kwargs come from the URL resolver.
        response = OfferView.as_view()(request, offer_slug='my-offer')
        print("Success!")
    except Exception as e:
        print(f"Caught exception: {e}")
        import traceback
        traceback.print_exc()

